/bin/bash -lc "python3 - <<'PY'
phys=set(); cores=[]
phys_ids=[]
with open('/proc/cpuinfo') as f:
    cur={}
    for line in f:
        line=line.strip()
        if not line:
            if 'physical id' in cur and 'core id' in cur:
                phys.add((cur['physical id'],cur['core id']))
            cur={}
            continue
        if ':' in line:
            k,v=[x.strip() for x in line.split(':',1)]
            cur[k]=v
    if 'physical id' in cur and 'core id' in cur:
        phys.add((cur['physical id'],cur['core id']))
print('unique physical cores', len(phys))
PY"

